{
  "name": "TOPTECH Smart Garden Dashboard",
  "description": "A high-performance, mobile-first dashboard for monitoring and controlling smart garden systems, featuring real-time soil moisture tracking, automated irrigation controls, and resource saving analytics."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum NavTab {
  PANEL = 'panel',
  HISTORY = 'history',
  DEVICES = 'devices',
  SETTINGS = 'settings'
}

export interface GardenStatus {
  moisture: number;
  temperature: number;
  battery: number;
  waterSaved: number;
  nextSchedule: string;
  isIrrigating: boolean;
  isOnline: boolean;
}

import React, { useState, useEffect, useCallback } from 'react';
import { NavTab, GardenStatus } from './types';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import Navigation from './components/Navigation';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<NavTab>(NavTab.PANEL);
  const [status, setStatus] = useState<GardenStatus>({
    moisture: 65,
    temperature: 24,
    battery: 88,
    waterSaved: 120,
    nextSchedule: "05:30",
    isIrrigating: false,
    isOnline: true
  });

  // Simulated live updates for moisture and battery
  useEffect(() => {
    const interval = setInterval(() => {
      setStatus(prev => ({
        ...prev,
        // Slowly change moisture if not irrigating
        moisture: prev.isIrrigating 
          ? Math.min(100, prev.moisture + 1) 
          : Math.max(0, prev.moisture - 0.05),
        // Slowly drain battery
        battery: Math.max(0, prev.battery - 0.01)
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const handleStartIrrigation = useCallback(() => {
    setStatus(prev => ({ ...prev, isIrrigating: !prev.isIrrigating }));
  }, []);

  return (
    <div className="flex flex-col min-h-screen pb-24">
      <Header isOnline={status.isOnline} />

      <main className="flex-1 max-w-md mx-auto w-full px-4 overflow-x-hidden">
        {activeTab === NavTab.PANEL && (
          <Dashboard 
            status={status} 
            onIrrigate={handleStartIrrigation} 
          />
        )}

        {activeTab === NavTab.HISTORY && (
          <div className="mt-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <span className="material-symbols-outlined text-primary text-6xl mb-4 opacity-50">history</span>
            <h2 className="text-xl font-bold">Sulama Geçmişi</h2>
            <p className="text-slate-500 dark:text-[#92c9a4] mt-2">Son 30 günlük veriler yakında burada.</p>
          </div>
        )}

        {activeTab === NavTab.DEVICES && (
          <div className="mt-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <span className="material-symbols-outlined text-primary text-6xl mb-4 opacity-50">router</span>
            <h2 className="text-xl font-bold">Cihaz Listesi</h2>
            <p className="text-slate-500 dark:text-[#92c9a4] mt-2">1 Aktif Hub, 3 Sensör bağlı.</p>
          </div>
        )}

        {activeTab === NavTab.SETTINGS && (
          <div className="mt-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <span className="material-symbols-outlined text-primary text-6xl mb-4 opacity-50">settings</span>
            <h2 className="text-xl font-bold">Ayarlar</h2>
            <p className="text-slate-500 dark:text-[#92c9a4] mt-2">Sistem yapılandırması ve kullanıcı profili.</p>
          </div>
        )}
      </main>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

