interface ScheduleModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (time: string, day: string) => void;
  currentTime: string;
}

const ScheduleModal: React.FC<ScheduleModalProps> = ({ isOpen, onClose, onSave, currentTime }) => {
  const [hour, setHour] = useState(currentTime.split(':')[0] || '05');
  const [minute, setMinute] = useState(currentTime.split(':')[1] || '30');
  const [selectedDay, setSelectedDay] = useState('Yarın');

  const days = ['Bugün', 'Yarın', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi', 'Pazar'];
  const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
  const minutes = Array.from({ length: 12 }, (_, i) => (i * 5).toString().padStart(2, '0'));

  const handleSave = () => {
    onSave(`${hour}:${minute}`, selectedDay);
    onClose();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Zamanlayıcı Ayarla">
      <div className="flex flex-col gap-8">
        {/* Stylized Time Picker */}
        <div className="flex justify-center items-center gap-4 bg-background-dark/30 py-8 rounded-3xl border border-border-dark/30">
          <div className="flex flex-col items-center gap-2">
            <button onClick={() => setHour(prev => hours[(parseInt(prev) + 1) % 24])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_less</span>
            </button>
            <div className="text-5xl font-black text-white w-16 text-center tabular-nums">{hour}</div>
            <button onClick={() => setHour(prev => hours[(parseInt(prev) + 23) % 24])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_more</span>
            </button>
          </div>

          <div className="text-4xl font-black text-primary animate-pulse">:</div>

          <div className="flex flex-col items-center gap-2">
            <button onClick={() => setMinute(prev => minutes[(minutes.indexOf(prev) + 1) % 12])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_less</span>
            </button>
            <div className="text-5xl font-black text-white w-16 text-center tabular-nums">{minute}</div>
            <button onClick={() => setMinute(prev => minutes[(minutes.indexOf(prev) + 11) % 12])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_more</span>
            </button>
          </div>
        </div>

        {/* Day Picker */}
        <div className="flex flex-col gap-3">
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest ml-1">GÜN SEÇİN</label>
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide no-scrollbar">
            {days.map(day => (
              <button
                key={day}
                onClick={() => setSelectedDay(day)}
                className={`px-4 py-2.5 rounded-xl text-sm font-bold whitespace-nowrap transition-all border ${
                  selectedDay === day 
                    ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/20' 
                    : 'bg-surface-dark/50 text-slate-400 border-border-dark hover:border-slate-500'
                }`}
              >
                {day}
              </button>
            ))}
          </div>
        </div>

        <button
          onClick={handleSave}
          className="w-full bg-primary text-background-dark font-extrabold text-lg h-14 rounded-2xl glow-button active:scale-95 transition-all mt-2"
        >
          Programı Kaydet
        </button>
      </div>
    </Modal>
  );
};

