import React, { useState, useEffect, useCallback } from 'react';
import { NavTab, GardenStatus, Land, WeatherCondition, ForecastDay } from './types';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import Navigation from './components/Navigation';
import LandsView from './components/LandsView';
import HistoryView from './components/HistoryView';
import WeatherView from './components/WeatherView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<NavTab>(NavTab.PANEL);
  const [lands, setLands] = useState<Land[]>([
    { id: '1', name: 'Zeytinlik', location: 'Muğla, Milas', sensorCount: 4, image: 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&q=80&w=600', coordinates: '37.3167, 27.7833' },
    { id: '2', name: 'Arka Bahçe', location: 'İstanbul, Beykoz', sensorCount: 2, image: 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&q=80&w=600', coordinates: '41.1333, 29.1000' },
  ]);
  const [selectedLandId, setSelectedLandId] = useState<string>('1');

  const [status, setStatus] = useState<GardenStatus>({
    moisture: 65,
    temperature: 24,
    battery: 88,
    waterSaved: 120,
    nextSchedule: "05:30",
    isIrrigating: false,
    isOnline: true,
    condition: 'Sunny',
    forecast: []
  });

  const mapWeatherCode = (code: number): WeatherCondition => {
    if (code === 0) return 'Sunny';
    if (code >= 1 && code <= 3) return 'PartlyCloudy';
    if (code === 45 || code === 48) return 'Cloudy';
    if (code >= 51) return 'Rainy';
    return 'Sunny';
  };

  const fetchWeather = useCallback(async (coords: string) => {
    try {
      const [lat, lon] = coords.split(',').map(c => c.trim());
      if (!lat || !lon) return;

      const response = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true&daily=weathercode,temperature_2m_max,temperature_2m_min&timezone=auto`);
      const data = await response.json();

      if (data && data.current_weather) {
        const { temperature, weathercode } = data.current_weather;

        const forecast: ForecastDay[] = data.daily.time.map((time: string, i: number) => {
          const date = new Date(time);
          const days = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];
          return {
            date: i === 0 ? 'Bugün' : days[date.getDay()],
            maxTemp: Math.round(data.daily.temperature_2m_max[i]),
            minTemp: Math.round(data.daily.temperature_2m_min[i]),
            condition: mapWeatherCode(data.daily.weathercode[i])
          };
        }).slice(0, 5);

        setStatus(prev => ({
          ...prev,
          temperature: Math.round(temperature),
          condition: mapWeatherCode(weathercode),
          forecast
        }));
      }
    } catch (error) {
      console.error("Weather fetch failed:", error);
    }
  }, []);

  // Fetch weather when selected land changes
  useEffect(() => {
    const activeLand = lands.find(l => l.id === selectedLandId);
    if (activeLand?.coordinates) {
      fetchWeather(activeLand.coordinates);
    }
  }, [selectedLandId, lands, fetchWeather]);

  // Simulated live updates for moisture and battery
  useEffect(() => {
    const interval = setInterval(() => {
      setStatus(prev => ({
        ...prev,
        moisture: prev.isIrrigating 
          ? Math.min(100, prev.moisture + 1) 
          : Math.max(0, prev.moisture - 0.05),
        battery: Math.max(0, prev.battery - 0.01)
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const handleStartIrrigation = useCallback(() => {
    setStatus(prev => ({ ...prev, isIrrigating: !prev.isIrrigating }));
  }, []);

  const handleUpdateSchedule = useCallback((time: string, day: string) => {
    setStatus(prev => ({ ...prev, nextSchedule: time }));
    // In a real app, we'd also store the day, but here we just update the time string displayed.
    console.log(`Schedule updated to ${time} on ${day}`);
  }, []);

  const handleAddLand = (newLand: Land) => {
    setLands(prev => [...prev, newLand]);
    setSelectedLandId(newLand.id);
    setActiveTab(NavTab.PANEL);
  };

  const handleSelectLand = (id: string) => {
    setSelectedLandId(id);
    setActiveTab(NavTab.PANEL);
  };

  const activeLand = lands.find(l => l.id === selectedLandId);

  return (
    <div className="flex flex-col min-h-screen pb-24">
      <Header isOnline={status.isOnline} />

      <main className="flex-1 max-w-md mx-auto w-full px-4 overflow-x-hidden">
        {activeTab === NavTab.PANEL && (
          <Dashboard 
            status={status} 
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
            onIrrigate={handleStartIrrigation} 
            onUpdateSchedule={handleUpdateSchedule}
          />
        )}

        {activeTab === NavTab.WEATHER && (
          <WeatherView 
            status={status}
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
          />
        )}

        {activeTab === NavTab.HISTORY && (
          <HistoryView />
        )}

        {activeTab === NavTab.LANDS && (
          <LandsView 
            lands={lands} 
            selectedLandId={selectedLandId}
            onAddLand={handleAddLand}
            onSelectLand={handleSelectLand}
          />
        )}

        {activeTab === NavTab.SETTINGS && (
          <div className="mt-12 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
            <span className="material-symbols-outlined text-primary text-6xl mb-4 opacity-50">settings</span>
            <h2 className="text-xl font-bold">Ayarlar</h2>
            <p className="text-slate-500 dark:text-[#92c9a4] mt-2">Sistem yapılandırması ve kullanıcı profili.</p>
          </div>
        )}
      </main>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import Modal from './Modal';

interface ScheduleModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (time: string, day: string) => void;
  currentTime: string;
}

const ScheduleModal: React.FC<ScheduleModalProps> = ({ isOpen, onClose, onSave, currentTime }) => {
  const [hour, setHour] = useState(currentTime.split(':')[0] || '05');
  const [minute, setMinute] = useState(currentTime.split(':')[1] || '30');

  const today = new Date();
  const [selectedDate, setSelectedDate] = useState<Date>(today);

  const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
  const minutes = Array.from({ length: 12 }, (_, i) => (i * 5).toString().padStart(2, '0'));

  const handleSave = () => {
    const dayStr = selectedDate.toLocaleDateString('tr-TR', { day: 'numeric', month: 'long' });
    onSave(`${hour}:${minute}`, dayStr);
    onClose();
  };

  // Calendar logic
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();
  const monthName = today.toLocaleString('tr-TR', { month: 'long' });

  const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentYear, currentMonth, 1).getDay();
  const startOffset = (firstDayOfMonth + 6) % 7; // Monday start

  const calendarDays = Array.from({ length: daysInMonth }, (_, i) => i + 1);
  const weekdays = ['PT', 'SA', 'ÇA', 'PE', 'CU', 'CT', 'PZ'];

  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Zamanlayıcı Ayarla">
      <div className="flex flex-col gap-6">
        {/* Stylized Time Picker */}
        <div className="flex justify-center items-center gap-4 bg-background-dark/30 py-6 rounded-3xl border border-border-dark/30">
          <div className="flex flex-col items-center gap-1">
            <button onClick={() => setHour(prev => hours[(parseInt(prev) + 1) % 24])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_less</span>
            </button>
            <div className="text-5xl font-black text-white w-16 text-center tabular-nums">{hour}</div>
            <button onClick={() => setHour(prev => hours[(parseInt(prev) + 23) % 24])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_more</span>
            </button>
          </div>

          <div className="text-4xl font-black text-primary animate-pulse">:</div>

          <div className="flex flex-col items-center gap-1">
            <button onClick={() => setMinute(prev => minutes[(minutes.indexOf(prev) + 1) % 12])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_less</span>
            </button>
            <div className="text-5xl font-black text-white w-16 text-center tabular-nums">{minute}</div>
            <button onClick={() => setMinute(prev => minutes[(minutes.indexOf(prev) + 11) % 12])} className="text-slate-500 hover:text-primary transition-colors">
              <span className="material-symbols-outlined">expand_more</span>
            </button>
          </div>
        </div>

        {/* Calendar Picker */}
        <div className="flex flex-col gap-3">
          <div className="flex justify-between items-center px-1">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">TARİH SEÇİN</label>
            <span className="text-xs font-bold text-primary">{monthName} {currentYear}</span>
          </div>

          <div className="bg-surface-dark/40 border border-border-dark/30 rounded-2xl p-3">
            <div className="grid grid-cols-7 gap-y-2 text-center mb-2">
              {weekdays.map(wd => (
                <div key={wd} className="text-[8px] font-black text-slate-500">{wd}</div>
              ))}

              {/* Empty slots for start of month */}
              {Array.from({ length: startOffset }).map((_, i) => (
                <div key={`empty-${i}`} className="h-8"></div>
              ))}

              {calendarDays.map(day => {
                const isSelected = selectedDate.getDate() === day && selectedDate.getMonth() === currentMonth;
                const isToday = today.getDate() === day && today.getMonth() === currentMonth;
                const isPast = day < today.getDate();

                return (
                  <button
                    key={day}
                    disabled={isPast}
                    onClick={() => setSelectedDate(new Date(currentYear, currentMonth, day))}
                    className={`
                      h-8 w-8 mx-auto flex items-center justify-center rounded-full text-xs font-bold transition-all
                      ${isSelected ? 'bg-primary text-background-dark scale-110' : ''}
                      ${!isSelected && isToday ? 'text-primary ring-1 ring-primary/30' : ''}
                      ${!isSelected && !isToday && !isPast ? 'text-white hover:bg-white/10' : ''}
                      ${isPast ? 'text-slate-700 cursor-not-allowed' : 'cursor-pointer'}
                    `}
                  >
                    {day}
                  </button>
                );
              })}
            </div>
          </div>
        </div>

        <button
          onClick={handleSave}
          className="w-full bg-primary text-background-dark font-extrabold text-lg h-14 rounded-2xl glow-button active:scale-95 transition-all mt-2"
        >
          Programı Kaydet
        </button>
      </div>
    </Modal>
  );
};

