  onUpdateSchedule: (time: string, day: string) => void;
}

const PlantAnimation: React.FC<{ progress: number; isIrrigating: boolean }> = ({ progress, isIrrigating }) => {
  // progress is 0 to 1
  const isFinished = progress >= 1;

  return (
    <div className="flex flex-col items-center justify-center py-4 gap-2">
      <div className="relative w-32 h-32 flex items-center justify-center">
        {/* Glow effect that grows with hydration */}
        <div 
          className="absolute inset-0 rounded-full bg-primary/20 blur-xl transition-all duration-1000"
          style={{ opacity: isIrrigating ? 0.2 + (progress * 0.6) : 0, transform: `scale(${0.8 + progress * 0.4})` }}
        ></div>

        {/* The Plant Icon */}
        <div className="relative transition-all duration-1000 ease-out flex flex-col items-center">
          <span 
            className={`material-symbols-outlined text-7xl transition-all duration-1000 ${isFinished ? 'scale-125' : 'scale-100'}`}
            style={{ 
              color: isFinished ? '#f472b6' : '#13ec5b', // Pink for flower, Green for plant
              filter: `saturate(${isFinished ? 1 : 0.2 + progress * 0.8}) sepia(${Math.max(0, 0.5 - progress)})`,
              opacity: isIrrigating || isFinished ? 1 : 0.4
            }}
          >
            {isFinished ? 'local_florist' : progress > 0.5 ? 'potted_plant' : 'eco'}
          </span>

          {/* Soil/Water effect */}
          {isIrrigating && !isFinished && (
            <div className="absolute -bottom-2 flex gap-1">
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce delay-75"></span>
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce delay-150"></span>
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce delay-300"></span>
            </div>
          )}
        </div>
      </div>

      <div className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 dark:text-[#92c9a4]">
        {isFinished ? 'SULAMA TAMAMLANDI' : isIrrigating ? 'BİTKİ CANLANIYOR...' : 'SULAMA BEKLENİYOR'}
      </div>
    </div>
  );
};

const Dashboard: React.FC<DashboardProps> = ({ status, activeLandName, onIrrigate, onUpdateSchedule }) => {
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [selectedDuration, setSelectedDuration] = useState(5); // Default 5 mins
  const [timeLeft, setTimeLeft] = useState(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const durations = [1, 5, 10, 15, 30, 60];

  const startIrrigation = () => {
    if (!status.isIrrigating) {
      setTimeLeft(selectedDuration * 60);
      onIrrigate();
    } else {
      stopIrrigation();
    }
  };

  const stopIrrigation = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setTimeLeft(0);
    if (status.isIrrigating) onIrrigate();
  };

  useEffect(() => {
    if (status.isIrrigating && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            clearInterval(timerRef.current!);
            onIrrigate(); // Stop irrigation via parent
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else if (!status.isIrrigating) {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [status.isIrrigating]);

  const progress = timeLeft === 0 && !status.isIrrigating ? 0 : (selectedDuration * 60 - timeLeft) / (selectedDuration * 60);

  // Display helper for MM:SS
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="animate-in fade-in duration-700">
      {/* System Status Header */}
      <div className="mt-6 mb-8 text-center">
        <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">{activeLandName}</h1>
        <p className="text-slate-500 dark:text-[#92c9a4] mt-1">
          {status.isIrrigating ? 'Sulama yapılıyor...' : 'Sistem aktif ve optimize ediliyor'}
        </p>
      </div>

      {/* Central Weather Hero Section */}
      <div className="flex justify-center my-6">
        <WeatherHero condition={status.condition} temperature={status.temperature} />
      </div>

      {/* Plant Animation Section */}
      <div className="mb-6">
        <PlantAnimation progress={progress} isIrrigating={status.isIrrigating} />
      </div>

      {/* Action Button & Spinner Picker */}
      <div className="px-4 py-4 flex flex-col gap-6 bg-white dark:bg-surface-dark/30 rounded-3xl border border-slate-200 dark:border-border-dark/50 p-6 shadow-sm">

        {/* Duration Spinner Picker */}
        <div className="flex flex-col gap-3">
          <div className="flex justify-between items-center px-1">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Süre Seçin (Dakika)</span>
            {status.isIrrigating && (
              <span className="text-sm font-black text-primary animate-pulse">{formatTime(timeLeft)} Kalan</span>
            )}
          </div>
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide no-scrollbar">
            {durations.map(d => (
              <button
                key={d}
                disabled={status.isIrrigating}
                onClick={() => setSelectedDuration(d)}
                className={`flex-1 min-w-[60px] h-12 rounded-xl text-sm font-bold border transition-all ${
                  selectedDuration === d 
                    ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/20' 
                    : 'bg-white dark:bg-surface-dark text-slate-500 border-slate-200 dark:border-border-dark opacity-60'
                } ${status.isIrrigating ? 'cursor-not-allowed' : ''}`}
              >
                {d} dk
              </button>
            ))}
          </div>
        </div>

        <button 
          onClick={startIrrigation}
          className={`w-full flex items-center justify-center gap-3 ${status.isIrrigating ? 'bg-red-500 text-white' : 'bg-primary text-background-dark'} font-extrabold text-lg h-16 rounded-2xl glow-button transition-all active:scale-95`}
        >
          <span className={`material-symbols-outlined font-bold ${status.isIrrigating ? 'animate-bounce' : ''}`}>
            {status.isIrrigating ? 'stop_circle' : 'water_drop'}
          </span>
          <span>{status.isIrrigating ? 'Sulamayı Durdur' : 'Sulamayı Başlat'}</span>
        </button>
      </div>

      {/* Section Header */}
      <div className="flex items-center justify-between px-2 mt-8 mb-2">
        <h3 className="text-lg font-bold text-slate-900 dark:text-white">Hızlı Bakış</h3>
      </div>

      {/* Quick Grid Tiles */}
      <div className="grid grid-cols-2 gap-4 pb-12">
        {/* Soil Moisture */}
        <StatusTile 
          icon="opacity" 
          label="Toprak Nemi" 
          value={`%${Math.round(status.moisture)}`} 
          subValue={status.moisture > 60 ? "Nemli - İdeal" : "Kuru - Sulama Önerilir"} 
        />

        {/* Next Session */}
        <div onClick={() => setIsScheduleModalOpen(true)}>
          <StatusTile 
            icon="schedule" 
            label="Sonraki Oturum" 
            value={status.nextSchedule} 
            subValue={status.nextScheduleDay} 
          />
        </div>

        {/* Remaining Water Tile */}
        <div className="col-span-2 flex items-center gap-5 rounded-2xl border border-slate-200 dark:border-border-dark bg-white dark:bg-surface-dark p-5 shadow-sm">
          <div className="h-14 w-14 rounded-xl bg-blue-500/10 flex items-center justify-center">
            <span className="material-symbols-outlined text-blue-400 text-3xl">water</span>
          </div>
          <div className="flex flex-col">
