import React, { useState, useEffect, useRef } from 'react';
import { GardenStatus } from '../types';
import WeatherHero from './WeatherHero';
import StatusTile from './StatusTile';
import ScheduleModal from './ScheduleModal';

interface DashboardProps {
  status: GardenStatus;
  activeLandName: string;
  onIrrigate: () => void;
  onUpdateSchedule: (time: string, day: string) => void;
}

const PlantAnimation: React.FC<{ progress: number; isIrrigating: boolean }> = ({ progress, isIrrigating }) => {
  // progress is 0 to 1
  const isFinished = progress >= 1;
  const growthScale = 0.5 + progress * 0.5; // Starts small, grows to full size

  return (
    <div className="flex flex-col items-center justify-center py-8 relative">
      <div className="relative w-48 h-48 flex items-center justify-center">
        {/* Ambient Glow */}
        <div 
          className="absolute inset-0 rounded-full bg-primary/10 blur-3xl transition-all duration-1000"
          style={{ 
            opacity: isIrrigating ? 0.4 : 0.1, 
            transform: `scale(${1 + progress * 0.5})` 
          }}
        ></div>

        {/* Growth Progress Ring (Subtle) */}
        <svg className="absolute w-full h-full -rotate-90 opacity-20">
          <circle 
            cx="96" cy="96" r="80" 
            fill="transparent" 
            stroke="#13ec5b" 
            strokeWidth="2" 
            strokeDasharray="502" 
            strokeDashoffset={502 * (1 - progress)}
            className="transition-all duration-500"
          />
        </svg>

        {/* Animated Plant SVG */}
        <div className="relative z-10 transition-all duration-1000 ease-out" style={{ transform: `scale(${growthScale}) translateY(${(1 - progress) * 10}px)` }}>
          <svg width="120" height="120" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
            {/* Stalk */}
            <path 
              d="M50 90C50 90 48 70 50 40" 
              stroke="#326744" 
              strokeWidth="4" 
              strokeLinecap="round" 
              className="transition-all duration-1000"
              style={{ stroke: isFinished ? '#13ec5b' : '#326744' }}
            />

            {/* Left Leaf */}
            <path 
              d="M50 70C30 70 20 50 50 60" 
              fill={isIrrigating ? "#13ec5b" : "#326744"} 
              className="transition-all duration-1000 opacity-80"
              style={{ transform: `rotate(${-20 + progress * 20}deg)`, transformOrigin: '50px 70px' }}
            />

            {/* Right Leaf */}
            <path 
              d="M50 65C70 65 80 45 50 55" 
              fill={isIrrigating ? "#13ec5b" : "#326744"} 
              className="transition-all duration-1000 opacity-80"
              style={{ transform: `rotate(${20 - progress * 20}deg)`, transformOrigin: '50px 65px' }}
            />

            {/* Blooming Flower (Only appears as progress increases) */}
            <g style={{ opacity: Math.max(0, (progress - 0.7) * 3.3), transform: `scale(${progress})`, transformOrigin: '50px 40px' }} className="transition-all duration-700">
              <circle cx="50" cy="40" r="10" fill="#f472b6" /> {/* Pink Flower Center */}
              <circle cx="40" cy="35" r="6" fill="#fbcfe8" />
              <circle cx="60" cy="35" r="6" fill="#fbcfe8" />
              <circle cx="50" cy="25" r="6" fill="#fbcfe8" />
              <circle cx="45" cy="48" r="6" fill="#fbcfe8" />
              <circle cx="55" cy="48" r="6" fill="#fbcfe8" />
            </g>
          </svg>
        </div>

        {/* Rain particles when irrigating */}
        {isIrrigating && !isFinished && (
          <div className="absolute top-0 w-full h-1/2 overflow-hidden flex justify-around opacity-60">
            {[1, 2, 3, 4, 5].map(i => (
              <div 
                key={i} 
                className={`w-0.5 h-3 bg-blue-300 rounded-full animate-[drop_1s_infinite]`}
                style={{ animationDelay: `${i * 0.2}s`, left: `${i * 20}%` }}
              ></div>
            ))}
          </div>
        )}
      </div>

      <div className="mt-4 flex flex-col items-center gap-1">
         <div className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest transition-all duration-500 ${isIrrigating ? 'bg-primary text-background-dark shadow-lg shadow-primary/20' : 'bg-surface-dark text-slate-500'}`}>
            {isFinished ? 'SULAMA TAMAMLANDI' : isIrrigating ? 'CANLANIYOR...' : 'BEKLİYOR'}
         </div>
      </div>

      <style>{`
        @keyframes drop {
          0% { transform: translateY(-20px); opacity: 0; }
          50% { opacity: 1; }
          100% { transform: translateY(100px); opacity: 0; }
        }
      `}</style>
    </div>
  );
};

