        <svg className="absolute w-full h-full -rotate-90 pointer-events-none">
          <circle 
            cx="128" cy="128" r="110" 
            fill="transparent" 
            stroke="currentColor" 
            strokeWidth="0.5" 
            className="text-slate-200 dark:text-surface-dark opacity-30"
          />
          <circle 
            cx="128" cy="128" r="110" 
            fill="transparent" 
            stroke="url(#proRoseGradient)" 
            strokeWidth="4" 
            strokeDasharray="691" 
            strokeDashoffset={691 * (1 - progress)}
            strokeLinecap="round"
            className="transition-all duration-500 ease-out"
          />
          <defs>
            <linearGradient id="proRoseGradient" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#13ec5b" />
              <stop offset="100%" stopColor="#e11d48" />
            </linearGradient>
          </defs>
        </svg>

        {/* Professional Rose Morphing Animation */}
        <div 
          className="relative z-10 transition-all duration-1000 ease-out" 
          style={{ 
            transform: `scale(${growthScale}) translateY(${(1 - progress) * 12}px)`,
            filter: `drop-shadow(0 0 15px ${isFinished ? 'rgba(225, 29, 72, 0.4)' : 'rgba(19, 236, 91, 0.2)'})`
          }}
        >
          <svg width="160" height="160" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
            {/* Stalk */}
            <path 
              d="M50 98C50 98 48 82 50 45" 
              stroke={isFinished ? "#13ec5b" : "#2d5a3c"} 
              strokeWidth="3.5" 
              strokeLinecap="round" 
              className="transition-all duration-1000"
            />

            {/* Organic Leaves with Motion */}
            <path 
              d="M50 78C32 78 18 58 50 65" 
              fill={isIrrigating ? "#13ec5b" : "#2d5a3c"} 
              className="transition-all duration-1000 opacity-90"
              style={{ transform: `rotate(${-12 + progress * 12}deg)`, transformOrigin: '50px 78px' }}
            />
            <path 
              d="M50 72C68 72 82 52 50 58" 
              fill={isIrrigating ? "#13ec5b" : "#2d5a3c"} 
              className="transition-all duration-1000 opacity-90"
              style={{ transform: `rotate(${12 - progress * 12}deg)`, transformOrigin: '50px 72px' }}
            />

            {/* Bloom Cluster */}
            <g style={{ opacity: Math.max(0, (progress - 0.2) * 1.5), transform: `scale(${0.4 + progress * 0.6})`, transformOrigin: '50px 40px' }} className="transition-all duration-700">
              {/* Petals with shading */}
              <circle cx="50" cy="35" r="16" fill="#881337" className="transition-all duration-1000" />
              <path d="M50 20C35 20 25 35 50 45C75 35 65 20 50 20Z" fill="#be123c" style={{ transformOrigin: '50px 35px', transform: `rotate(${-15 + progress * 15}deg)` }} />
              <path d="M35 45C35 35 50 25 50 45C50 65 35 55 35 45Z" fill="#e11d48" style={{ opacity: 0.9 }} />
              <path d="M65 45C65 35 50 25 50 45C50 65 65 55 65 45Z" fill="#e11d48" style={{ opacity: 0.9 }} />
              <circle cx="50" cy="48" r="13" fill="#f43f5e" />

              {/* Core Detail */}
              <circle cx="50" cy="40" r="6" fill="#fb7185" className="animate-pulse" />
            </g>
          </svg>
        </div>

        {/* Rain particles */}
        {isIrrigating && !isFinished && (
          <div className="absolute top-0 w-full h-1/2 overflow-hidden flex justify-around opacity-40 pointer-events-none">
            {[1, 2, 3, 4, 5, 6].map(i => (
              <div 
                key={i} 
                className={`w-[1px] h-8 bg-gradient-to-b from-blue-300 to-transparent animate-[rain_0.7s_infinite]`}
                style={{ animationDelay: `${i * 0.12}s`, left: `${i * 16}%` }}
              ></div>
            ))}
          </div>
        )}
      </div>

      <div className="mt-4 flex flex-col items-center gap-1.5">
         <div className={`px-10 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.3em] transition-all duration-500 border ${isIrrigating ? 'bg-primary text-background-dark border-primary shadow-xl shadow-primary/20 animate-pulse' : 'bg-surface-dark text-slate-500 border-white/5'}`}>
            {isFinished ? 'BAŞARIYLA TAMAMLANDI' : isIrrigating ? 'ARAZİ SULANIYOR...' : 'SİSTEM HAZIR'}
         </div>
         {isIrrigating && (
           <div className="flex items-center gap-2 text-[9px] font-black text-primary/60 tracking-widest mt-1">
             <span className="w-1.5 h-1.5 rounded-full bg-primary animate-ping"></span>
             OTOMASYON AKTİF
           </div>
         )}
      </div>

      <style>{`
        @keyframes rain {
          0% { transform: translateY(-40px); opacity: 0; }
          40% { opacity: 1; }
          100% { transform: translateY(130px); opacity: 0; }
        }
      `}</style>
    </div>
  );
};

const Dashboard: React.FC<DashboardProps> = ({ status, activeLandName, onIrrigate, onUpdateSchedule }) => {
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [selectedMinutes, setSelectedMinutes] = useState(10);
  const [timeLeft, setTimeLeft] = useState(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const adjustMinutes = (amount: number) => {
    if (status.isIrrigating) return;
    setSelectedMinutes(prev => Math.max(1, Math.min(120, prev + amount)));
  };

  const startIrrigation = () => {
    if (!status.isIrrigating) {
      setTimeLeft(selectedMinutes * 60);
      onIrrigate();
    } else {
      stopIrrigation();
    }
  };

  const stopIrrigation = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setTimeLeft(0);
    if (status.isIrrigating) onIrrigate();
  };

  useEffect(() => {
    if (status.isIrrigating && timeLeft > 0) {
      if (timerRef.current) clearInterval(timerRef.current);

      timerRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            if (timerRef.current) clearInterval(timerRef.current);
            onIrrigate();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } else if (!status.isIrrigating) {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [status.isIrrigating]);

  const progress = (timeLeft === 0 && !status.isIrrigating) ? 0 : 
                   (timeLeft === 0 && status.isIrrigating) ? 0 : 
                   Math.max(0, Math.min(1, (selectedMinutes * 60 - timeLeft) / (selectedMinutes * 60)));

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="animate-in fade-in duration-700 pb-12 overflow-x-hidden">
      {/* System Status Header */}
      <div className="mt-6 mb-2 text-center">
        <h1 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">{activeLandName}</h1>
        <p className="text-slate-500 dark:text-[#92c9a4] text-[9px] font-black uppercase tracking-[0.25em] mt-1 opacity-60">
          PRO-SULAMA PANELİ v2.5
        </p>
      </div>

      {/* Hero Animation Area */}
      <div className="mb-4">
         <PlantAnimation progress={progress} isIrrigating={status.isIrrigating} />
      </div>

      {/* Controller Card - FIXED Centering and Clipping */}
      <div className="bg-white dark:bg-surface-dark/40 rounded-[2.5rem] border border-slate-200 dark:border-border-dark p-6 shadow-2xl relative overflow-hidden backdrop-blur-md mx-1">
        <div className="absolute top-0 left-0 w-full h-[3px] bg-gradient-to-r from-transparent via-primary/50 to-transparent"></div>

        <div className="flex flex-col items-center gap-8 w-full">
          <div className="flex flex-col items-center gap-5 w-full">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] text-center">SULAMA SÜRESİ KONTROLÜ</span>

            {/* Grid Layout for Perfect Centering */}
            <div className="grid grid-cols-5 items-center w-full px-1">
              {/* Left Button */}
              <div className="col-span-1 flex justify-start">
                <button 
                  onClick={() => adjustMinutes(-1)}
                  disabled={status.isIrrigating}
                  className="h-12 w-12 rounded-full border border-slate-200 dark:border-border-dark flex items-center justify-center text-slate-400 hover:text-primary transition-all active:scale-90 disabled:opacity-5"
                >
                  <span className="material-symbols-outlined text-2xl">remove</span>
                </button>
              </div>

              {/* Center Counter */}
              <div className="col-span-3 flex flex-col items-center justify-center">
                <div className="text-5xl font-black text-slate-900 dark:text-white tabular-nums leading-none tracking-tight">
                  {status.isIrrigating ? formatTime(timeLeft) : selectedMinutes}
                </div>
                <div className="text-[10px] font-black text-primary tracking-[0.2em] mt-3 uppercase whitespace-nowrap">
                  {status.isIrrigating ? 'KALAN SÜRE' : 'DAKİKA'}
                </div>
              </div>

              {/* Right Button */}
              <div className="col-span-1 flex justify-end">
                <button 
                  onClick={() => adjustMinutes(1)}
                  disabled={status.isIrrigating}
                  className="h-12 w-12 rounded-full border border-slate-200 dark:border-border-dark flex items-center justify-center text-slate-400 hover:text-primary transition-all active:scale-90 disabled:opacity-5"
                >
                  <span className="material-symbols-outlined text-2xl">add</span>
                </button>
              </div>
            </div>

            {/* Quick Presets Slider */}
            {!status.isIrrigating && (
              <div className="flex gap-2 w-full justify-center py-1">
                {[5, 10, 15, 30].map(m => (
                  <button 
                    key={m}
                    onClick={() => setSelectedMinutes(m)}
                    className={`px-4 py-2 rounded-full text-[10px] font-black border transition-all ${selectedMinutes === m ? 'bg-primary text-background-dark border-primary shadow-lg shadow-primary/20' : 'border-slate-200 dark:border-border-dark text-slate-500 hover:bg-white/5'}`}
                  >
                    {m} DK
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Large Action Button */}
          <button 
            onClick={startIrrigation}
            className={`w-full flex items-center justify-center gap-4 ${status.isIrrigating ? 'bg-rose-500 text-white' : 'bg-primary text-background-dark'} font-black text-xl h-20 rounded-[2rem] glow-button transition-all active:scale-[0.98] shadow-2xl relative group`}
          >
            <div className={`h-12 w-12 rounded-full flex items-center justify-center transition-colors ${status.isIrrigating ? 'bg-white/20' : 'bg-black/10'}`}>
              <span className={`material-symbols-outlined text-2xl font-bold ${status.isIrrigating ? 'animate-spin' : 'group-hover:rotate-12 transition-transform'}`}>
                {status.isIrrigating ? 'cached' : 'water_drop'}
              </span>
            </div>
            <span>{status.isIrrigating ? 'DURDUR' : 'BAŞLAT'}</span>
          </button>
        </div>
      </div>

      {/* Grid Status Tiles */}
      <div className="grid grid-cols-2 gap-4 mt-8 px-1">
        <StatusTile 
          icon="opacity" 
          label="Toprak Nemi" 
          value={`%${Math.round(status.moisture)}`} 
          subValue={status.moisture > 60 ? "Seviye İdeal" : "Kritik Seviye"} 
        />

        <div onClick={() => setIsScheduleModalOpen(true)}>
          <StatusTile 
            icon="event_note" 
            label="Planlanan" 
            value={status.nextSchedule} 
            subValue={status.nextScheduleDay} 
          />
        </div>

        <div className="col-span-2 flex items-center gap-6 rounded-3xl border border-slate-200 dark:border-border-dark bg-white dark:bg-surface-dark p-6 shadow-sm relative overflow-hidden">
          <div className="h-16 w-16 rounded-2xl bg-blue-500/10 flex items-center justify-center shrink-0">
            <span className="material-symbols-outlined text-blue-400 text-4xl">inventory_2</span>
          </div>
          <div className="flex flex-col">
            <div className="flex items-baseline gap-2">
              <h2 className="text-3xl font-black text-slate-900 dark:text-white">{status.waterRemaining}L</h2>
              <span className="text-[10px] font-black text-blue-400 tracking-widest uppercase">MEVCUT STOK</span>
            </div>
            <p className="text-[9px] text-slate-500 dark:text-[#92c9a4] font-bold uppercase tracking-[0.2em] mt-1 opacity-70">Tank doluluk oranı %{Math.round((status.waterRemaining/500)*100)}</p>
          </div>
        </div>
      </div>

      <ScheduleModal 
        isOpen={isScheduleModalOpen} 
        onClose={() => setIsScheduleModalOpen(false)} 
        onSave={onUpdateSchedule}
        currentTime={status.nextSchedule}
      />
    </div>
  );
};

export default Dashboard;

export enum NavTab {
  PANEL = 'panel',
  HISTORY = 'history',
  WEATHER = 'weather',
  LANDS = 'lands',
  SETTINGS = 'settings'
}

export type WeatherCondition = 'Sunny' | 'Cloudy' | 'Rainy' | 'PartlyCloudy';

export interface ForecastDay {
  date: string;
  maxTemp: number;
  minTemp: number;
  condition: WeatherCondition;
}

export interface GardenStatus {
  moisture: number;
  temperature: number;
  battery: number;
  waterSaved: number;
  waterRemaining: number;
  tankCapacity: number; // Added for user-defined tank capacity
  nextSchedule: string;
  nextScheduleDay: string;
  isIrrigating: boolean;
  isOnline: boolean;
  condition: WeatherCondition;
  forecast?: ForecastDay[];
}

export interface Land {
  id: string;
  name: string;
  location: string;
  sensorCount: number;
  image: string;
  phoneNumber?: string;
  coordinates?: string;
}

export interface IrrigationSession {
  id: string;
  location: string;
  time: string;
  startTime: string;
  endTime: string;
  duration: string;
  icon: string;
}

import React, { useState, useEffect, useCallback } from 'react';
import { NavTab, GardenStatus, Land, WeatherCondition, ForecastDay } from './types';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import Navigation from './components/Navigation';
import LandsView from './components/LandsView';
import HistoryView from './components/HistoryView';
import WeatherView from './components/WeatherView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<NavTab>(NavTab.PANEL);
  const [lands, setLands] = useState<Land[]>([
    { id: '1', name: 'Zeytinlik', location: 'Muğla, Milas', sensorCount: 4, image: 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&q=80&w=600', coordinates: '37.3167, 27.7833' },
    { id: '2', name: 'Arka Bahçe', location: 'İstanbul, Beykoz', sensorCount: 2, image: 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&q=80&w=600', coordinates: '41.1333, 29.1000' },
  ]);
  const [selectedLandId, setSelectedLandId] = useState<string>('1');

  const [status, setStatus] = useState<GardenStatus>({
    moisture: 65,
    temperature: 24,
    battery: 88,
    waterSaved: 120,
    waterRemaining: 439.5,
    tankCapacity: 500, // Default capacity
    nextSchedule: "05:30",
    nextScheduleDay: "Yarın Sabah",
    isIrrigating: false,
    isOnline: true,
    condition: 'Sunny',
    forecast: []
  });

  const mapWeatherCode = (code: number): WeatherCondition => {
    if (code === 0) return 'Sunny';
    if (code >= 1 && code <= 3) return 'PartlyCloudy';
    if (code === 45 || code === 48) return 'Cloudy';
    if (code >= 51) return 'Rainy';
    return 'Sunny';
  };

  const fetchWeather = useCallback(async (coords: string) => {
    try {
      const [lat, lon] = coords.split(',').map(c => c.trim());
      if (!lat || !lon) return;

      const response = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true&daily=weathercode,temperature_2m_max,temperature_2m_min&timezone=auto`);
      const data = await response.json();

      if (data && data.current_weather) {
        const { temperature, weathercode } = data.current_weather;

        const forecast: ForecastDay[] = data.daily.time.map((time: string, i: number) => {
          const date = new Date(time);
          const days = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];
          return {
            date: i === 0 ? 'Bugün' : days[date.getDay()],
            maxTemp: Math.round(data.daily.temperature_2m_max[i]),
            minTemp: Math.round(data.daily.temperature_2m_min[i]),
            condition: mapWeatherCode(data.daily.weathercode[i])
          };
        }).slice(0, 5);

        setStatus(prev => ({
          ...prev,
          temperature: Math.round(temperature),
          condition: mapWeatherCode(weathercode),
          forecast
        }));
      }
    } catch (error) {
      console.error("Weather fetch failed:", error);
    }
  }, []);

  useEffect(() => {
    const activeLand = lands.find(l => l.id === selectedLandId);
    if (activeLand?.coordinates) {
      fetchWeather(activeLand.coordinates);
    }
  }, [selectedLandId, lands, fetchWeather]);

  useEffect(() => {
    const interval = setInterval(() => {
      setStatus(prev => ({
        ...prev,
        moisture: prev.isIrrigating 
          ? Math.min(100, prev.moisture + 1) 
          : Math.max(0, prev.moisture - 0.05),
        battery: Math.max(0, prev.battery - 0.01),
        waterRemaining: prev.isIrrigating 
          ? Math.max(0, prev.waterRemaining - 0.5) 
          : prev.waterRemaining
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  const handleStartIrrigation = useCallback(() => {
    setStatus(prev => ({ ...prev, isIrrigating: !prev.isIrrigating }));
  }, []);

  const handleUpdateSchedule = useCallback((time: string, day: string) => {
    setStatus(prev => ({ ...prev, nextSchedule: time, nextScheduleDay: day }));
  }, []);

  const handleAddLand = (newLand: Land) => {
    setLands(prev => [...prev, newLand]);
    setSelectedLandId(newLand.id);
    setActiveTab(NavTab.PANEL);
  };

  const handleSelectLand = (id: string) => {
    setSelectedLandId(id);
    setActiveTab(NavTab.PANEL);
  };

  const activeLand = lands.find(l => l.id === selectedLandId);

  return (
    <div className="flex flex-col min-h-screen pb-24">
      <Header isOnline={status.isOnline} />

      <main className="flex-1 max-w-md mx-auto w-full px-4 overflow-x-hidden">
        {activeTab === NavTab.PANEL && (
          <Dashboard 
            status={status} 
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
            onIrrigate={handleStartIrrigation} 
            onUpdateSchedule={handleUpdateSchedule}
          />
        )}

        {activeTab === NavTab.WEATHER && (
          <WeatherView 
            status={status}
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
          />
        )}

        {activeTab === NavTab.HISTORY && (
          <HistoryView />
        )}

        {activeTab === NavTab.LANDS && (
          <LandsView 
            lands={lands} 
            selectedLandId={selectedLandId}
            onAddLand={handleAddLand}
            onSelectLand={handleSelectLand}
          />
        )}

        {activeTab === NavTab.SETTINGS && (
          <div className="mt-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
            <div className="mb-8 text-center">
              <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white">Ayarlar</h2>
              <p className="text-slate-500 dark:text-[#92c9a4] mt-1">Cihaz durumu ve parametreler</p>
            </div>

            <div className="flex flex-col gap-6">
              {/* Tank Capacity Setting */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-primary text-2xl">database</span>
                    <span className="font-bold text-lg text-slate-900 dark:text-white uppercase tracking-wider">Tank Kapasitesi</span>
                  </div>
                  <span className="text-2xl font-black text-primary">{status.tankCapacity}L</span>
                </div>
                <input 
                  type="range" 
                  min="100" 
                  max="5000" 
                  step="50"
                  value={status.tankCapacity} 
                  onChange={(e) => setStatus(prev => ({ ...prev, tankCapacity: parseInt(e.target.value) }))}
                  className="w-full h-2 bg-slate-100 dark:bg-border-dark rounded-lg appearance-none cursor-pointer accent-primary"
                />
                <div className="flex justify-between text-[10px] font-bold text-slate-400 mt-2 uppercase">
                  <span>100L</span>
                  <span>5000L</span>
                </div>
              </div>

              {/* Device Battery */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-3">
                    <span className={`material-symbols-outlined text-primary text-2xl ${status.battery < 20 ? 'text-red-500 animate-pulse' : ''}`}>
                      {status.battery > 80 ? 'battery_full' : status.battery > 20 ? 'battery_std' : 'battery_alert'}
                    </span>
                    <span className="font-bold text-lg text-slate-900 dark:text-white uppercase tracking-wider">Cihaz Bataryası</span>
                  </div>
                  <span className="text-2xl font-black text-primary">{Math.round(status.battery)}%</span>
                </div>
                <div className="h-2 w-full rounded-full bg-slate-100 dark:bg-border-dark overflow-hidden">
                  <div 
                    className={`h-full rounded-full transition-all duration-1000 ${status.battery < 20 ? 'bg-red-500' : 'bg-primary'}`} 
                    style={{ width: `${status.battery}%` }}
                  ></div>
                </div>
              </div>

              {/* Water Savings */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark shadow-sm flex items-center gap-5">
                <div className="h-16 w-16 rounded-2xl bg-primary/10 flex items-center justify-center">
                  <span className="material-symbols-outlined text-primary text-4xl">eco</span>
                </div>
                <div className="flex flex-col">
                  <div className="flex items-baseline gap-1">
                    <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white">{status.waterSaved}L</h2>
                    <span className="text-sm font-bold text-primary">Tasarruf</span>
                  </div>
                  <p className="text-xs text-slate-500 dark:text-[#92c9a4] font-medium leading-tight">Bu ay akıllı sulama ile elde edilen toplam verim</p>
                </div>
              </div>

              {/* General Settings Placeholder */}
              <div className="mt-4 flex flex-col gap-3">
                <button className="flex items-center justify-between p-4 bg-slate-100 dark:bg-surface-dark/50 rounded-2xl border border-transparent hover:border-primary/50 transition-all">
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-slate-500">notifications</span>
                    <span className="font-bold text-sm">Bildirim Ayarları</span>
                  </div>
                  <span className="material-symbols-outlined text-slate-400">chevron_right</span>
                </button>
                <button className="flex items-center justify-between p-4 bg-slate-100 dark:bg-surface-dark/50 rounded-2xl border border-transparent hover:border-primary/50 transition-all">
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-slate-500">security</span>
                    <span className="font-bold text-sm">Cihaz Güvenliği</span>
                  </div>
                  <span className="material-symbols-outlined text-slate-400">chevron_right</span>
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

