const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<NavTab>(NavTab.PANEL);
  const [user, setUser] = useState<any>(null); // Firebase user
  const [isInitializing, setIsInitializing] = useState(true);
  const [isDeviceInfoModalOpen, setIsDeviceInfoModalOpen] = useState(false);
  const [lands, setLands] = useState<Land[]>([
    { id: '1', name: 'Zeytinlik', location: 'Muğla, Milas', sensorCount: 4, image: 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&q=80&w=600', coordinates: '37.3167, 27.7833' },
    { id: '2', name: 'Arka Bahçe', location: 'İstanbul, Beykoz', sensorCount: 2, image: 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&q=80&w=600', coordinates: '41.1333, 29.1000' },
  ]);
  const [selectedLandId, setSelectedLandId] = useState<string>('1');

  const [status, setStatus] = useState<GardenStatus>({
    moisture: 65,
    temperature: 24,
    battery: 88,
    waterSaved: 120,
    waterRemaining: 439.5,
    tankCapacity: 500,
    nextSchedule: "05:30",
    nextScheduleDay: "Yarın Sabah",
    isIrrigating: false,
    isOnline: true,
    isScheduleActive: true,
    condition: 'Sunny',
    forecast: []
  });

  // Simulation of persistent login
  useEffect(() => {
    const storedUser = localStorage.getItem('toptech_user');
    if (storedUser) setUser(JSON.parse(storedUser));
    setIsInitializing(false);
  }, []);

  const handleLogin = (userData: any) => {
    setUser(userData);
    localStorage.setItem('toptech_user', JSON.stringify({ email: userData }));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('toptech_user');
  };

  const mapWeatherCode = (code: number): WeatherCondition => {
    if (code === 0) return 'Sunny';
    if (code >= 1 && code <= 3) return 'PartlyCloudy';
    if (code === 45 || code === 48) return 'Cloudy';
    if (code >= 51) return 'Rainy';
    return 'Sunny';
  };

  const fetchWeather = useCallback(async (coords: string) => {
    try {
      const [lat, lon] = coords.split(',').map(c => c.trim());
      if (!lat || !lon) return;

      const response = await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true&daily=weathercode,temperature_2m_max,temperature_2m_min&timezone=auto`);
      const data = await response.json();

      if (data && data.current_weather) {
        const { temperature, weathercode } = data.current_weather;

        const forecast: ForecastDay[] = data.daily.time.map((time: string, i: number) => {
          const date = new Date(time);
          const days = ['Pazar', 'Pazartesi', 'Salı', 'Çarşamba', 'Perşembe', 'Cuma', 'Cumartesi'];
          return {
            date: i === 0 ? 'Bugün' : days[date.getDay()],
            maxTemp: Math.round(data.daily.temperature_2m_max[i]),
            minTemp: Math.round(data.daily.temperature_2m_min[i]),
            condition: mapWeatherCode(data.daily.weathercode[i])
          };
        }).slice(0, 5);

        setStatus(prev => ({
          ...prev,
          temperature: Math.round(temperature),
          condition: mapWeatherCode(weathercode),
          forecast
        }));
      }
    } catch (error) {
      console.error("Weather fetch failed:", error);
    }
  }, []);

  useEffect(() => {
    if (!user) return;
    const activeLand = lands.find(l => l.id === selectedLandId);
    if (activeLand?.coordinates) {
      fetchWeather(activeLand.coordinates);
    }
  }, [selectedLandId, lands, fetchWeather, user]);

  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => {
      setStatus(prev => ({
        ...prev,
        moisture: prev.isIrrigating 
          ? Math.min(100, prev.moisture + 1) 
          : Math.max(0, prev.moisture - 0.05),
        battery: Math.max(0, prev.battery - 0.01),
        waterRemaining: prev.isIrrigating 
          ? Math.max(0, prev.waterRemaining - 0.5) 
          : prev.waterRemaining
      }));
    }, 3000);

    return () => clearInterval(interval);
  }, [user]);

  const handleStartIrrigation = useCallback(() => {
    setStatus(prev => ({ ...prev, isIrrigating: !prev.isIrrigating }));
  }, []);

  const handleUpdateSchedule = useCallback((time: string, day: string) => {
    setStatus(prev => ({ ...prev, nextSchedule: time, nextScheduleDay: day }));
  }, []);

  const handleToggleSchedule = useCallback(() => {
    setStatus(prev => ({ ...prev, isScheduleActive: !prev.isScheduleActive }));
  }, []);

  const handleAddLand = (newLand: Land) => {
    setLands(prev => [...prev, newLand]);
    setSelectedLandId(newLand.id);
    setActiveTab(NavTab.PANEL);
  };

  const handleSelectLand = (id: string) => {
    setSelectedLandId(id);
    setActiveTab(NavTab.PANEL);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-background-dark flex items-center justify-center">
        <div className="h-16 w-16 border-4 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  if (!user) {
    return <LoginView onLogin={handleLogin} />;
  }

  const activeLand = lands.find(l => l.id === selectedLandId);

  return (
    <div className="flex flex-col min-h-screen pb-24 relative">
      <Header isOnline={status.isOnline} />

      <main className="flex-1 max-w-md mx-auto w-full px-4 overflow-x-hidden">
        {activeTab === NavTab.PANEL && (
          <Dashboard 
            status={status} 
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
            onIrrigate={handleStartIrrigation} 
            onUpdateSchedule={handleUpdateSchedule}
            onToggleSchedule={handleToggleSchedule}
          />
        )}

        {activeTab === NavTab.WEATHER && (
          <WeatherView 
            status={status}
            activeLandName={activeLand?.name || "Arazi Seçilmedi"}
          />
        )}

        {activeTab === NavTab.HISTORY && (
          <HistoryView />
        )}

        {activeTab === NavTab.LANDS && (
          <LandsView 
            lands={lands} 
            selectedLandId={selectedLandId}
            onAddLand={handleAddLand}
            onSelectLand={handleSelectLand}
          />
        )}

        {activeTab === NavTab.SETTINGS && (
          <div className="mt-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
            <div className="mb-8 text-center">
              <h2 className="text-3xl font-extrabold text-slate-900 dark:text-white">Ayarlar</h2>
              <p className="text-slate-500 dark:text-[#92c9a4] mt-1">Cihaz durumu ve parametreler</p>
            </div>

            <div className="flex flex-col gap-6">
              {/* Profile Card */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark flex items-center gap-4 shadow-sm">
                <div className="h-14 w-14 rounded-2xl bg-primary/10 flex items-center justify-center">
                  <span className="material-symbols-outlined text-primary text-3xl">account_circle</span>
                </div>
                <div className="flex-1">
                  <h3 className="font-bold text-slate-900 dark:text-white uppercase tracking-wider text-xs">Aktif Kullanıcı</h3>
                  <p className="text-slate-500 text-sm truncate">{user.email}</p>
                </div>
                <button 
                  onClick={handleLogout}
                  className="p-3 rounded-xl bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white transition-colors"
                >
                  <span className="material-symbols-outlined">logout</span>
                </button>
              </div>

              {/* Tank Capacity Setting */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-primary text-2xl">database</span>
                    <span className="font-bold text-lg text-slate-900 dark:text-white uppercase tracking-wider">Tank Kapasitesi</span>
                  </div>
                  <div className="flex flex-col items-end">
                    <span className="text-2xl font-black text-primary">{status.tankCapacity}L</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase">({(status.tankCapacity / 1000).toFixed(1)} Ton)</span>
                  </div>
                </div>
                <input 
                  type="range" 
                  min="100" 
                  max="15000" 
                  step="100"
                  value={status.tankCapacity} 
                  onChange={(e) => setStatus(prev => ({ ...prev, tankCapacity: parseInt(e.target.value) }))}
                  className="w-full h-2 bg-slate-100 dark:bg-border-dark rounded-lg appearance-none cursor-pointer accent-primary"
                />
                <div className="flex justify-between text-[10px] font-bold text-slate-400 mt-2 uppercase">
                  <span>100L</span>
                  <span>15.000L</span>
                </div>
              </div>

              {/* Device Battery */}
              <div className="bg-white dark:bg-surface-dark p-6 rounded-3xl border border-slate-200 dark:border-border-dark shadow-sm">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-3">
                    <span className={`material-symbols-outlined text-primary text-2xl ${status.battery < 20 ? 'text-red-500 animate-pulse' : ''}`}>
                      {status.battery > 80 ? 'battery_full' : status.battery > 20 ? 'battery_std' : 'battery_alert'}
                    </span>
                    <span className="font-bold text-lg text-slate-900 dark:text-white uppercase tracking-wider">Cihaz Bataryası</span>
                  </div>
                  <span className="text-2xl font-black text-primary">{Math.round(status.battery)}%</span>
                </div>
                <div className="h-2 w-full rounded-full bg-slate-100 dark:bg-border-dark overflow-hidden">
                  <div 
                    className={`h-full rounded-full transition-all duration-1000 ${status.battery < 20 ? 'bg-red-500' : 'bg-primary'}`} 
                    style={{ width: `${status.battery}%` }}
                  ></div>
                </div>
              </div>

              {/* General Settings */}
              <div className="mt-4 flex flex-col gap-3">
                <button className="flex items-center justify-between p-4 bg-white dark:bg-surface-dark rounded-2xl border border-slate-200 dark:border-border-dark hover:border-primary/50 transition-all shadow-sm">
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-slate-500">notifications</span>
                    <span className="font-bold text-sm">Bildirim Ayarları</span>
                  </div>
                  <span className="material-symbols-outlined text-slate-400">chevron_right</span>
                </button>
                <button 
                  onClick={() => setIsDeviceInfoModalOpen(true)}
                  className="flex items-center justify-between p-4 bg-white dark:bg-surface-dark rounded-2xl border border-slate-200 dark:border-border-dark hover:border-primary/50 transition-all shadow-sm"
                >
                  <div className="flex items-center gap-3">
                    <span className="material-symbols-outlined text-slate-500">info</span>
                    <span className="font-bold text-sm">Cihaz Bilgisi</span>
                  </div>
                  <span className="material-symbols-outlined text-slate-400">chevron_right</span>
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Device Info Modal */}
      <Modal 
        isOpen={isDeviceInfoModalOpen} 
        onClose={() => setIsDeviceInfoModalOpen(false)} 
        title="Sistem Cihaz Durumu"
      >
        <div className="flex flex-col gap-4">
          <div className="p-4 rounded-2xl bg-background-dark/30 border border-border-dark/50 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="material-symbols-outlined text-primary">videocam</span>
              <span className="text-sm font-bold text-white">Güvenlik Kamerası</span>
            </div>
            <span className="text-xs font-black text-primary uppercase bg-primary/10 px-2 py-0.5 rounded-full">ÇEVRİMİÇİ</span>
          </div>

          <div className="p-4 rounded-2xl bg-background-dark/30 border border-border-dark/50 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="material-symbols-outlined text-yellow-400">solar_power</span>
              <span className="text-sm font-bold text-white">Güneş Paneli</span>
            </div>
            <div className="flex flex-col items-end">
              <span className="text-xs font-black text-yellow-400 uppercase">ŞARJ OLUYOR</span>
              <span className="text-[10px] text-slate-400">14.2V Giriş</span>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-background-dark/30 border border-border-dark/50 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="material-symbols-outlined text-primary">tungsten</span>
              <span className="text-sm font-bold text-white">Bahçe Aydınlatması</span>
            </div>
            <div className="flex flex-col items-end">
              <span className="text-xs font-black text-primary uppercase">AKTİF</span>
              <span className="text-[10px] text-slate-400">Gece Modu</span>
            </div>
          </div>

          <div className="p-4 rounded-2xl bg-background-dark/30 border border-border-dark/50">
            <div className="flex items-center gap-3 mb-3">
              <span className="material-symbols-outlined text-blue-400">sensors</span>
              <span className="text-sm font-bold text-white">Nem Sensörleri (x4)</span>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {[1, 2, 3, 4].map(id => (
                <div key={id} className="flex items-center justify-between bg-black/20 p-2 rounded-lg text-[10px]">
                  <span className="text-slate-400 font-bold">#0{id}</span>
                  <span className="text-primary font-black">AKTİF</span>
                </div>
              ))}
            </div>
          </div>

          <button 
            onClick={() => setIsDeviceInfoModalOpen(false)}
            className="w-full mt-4 bg-primary text-background-dark font-extrabold text-lg h-14 rounded-2xl active:scale-95 transition-all"
          >
            Tamam
          </button>
        </div>
      </Modal>

      <Navigation activeTab={activeTab} onTabChange={setActiveTab} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface LoginViewProps {
  onLogin: (email: string) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    // Simüle edilmiş Firebase Auth süreci
    setTimeout(() => {
      onLogin(email);
      setLoading(false);
    }, 1800);
  };

  const handleGoogleLogin = () => {
    setLoading(true);
    setTimeout(() => {
      onLogin('google-user@gmail.com');
      setLoading(false);
    }, 1800);
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-background-dark flex items-center justify-center p-6 overflow-hidden">
      {/* Fütüristik Arka Plan Katmanları */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Teknik Grid */}
        <div className="absolute inset-0 opacity-[0.03]" style={{ backgroundImage: 'radial-gradient(#13ec5b 1px, transparent 1px)', backgroundSize: '32px 32px' }}></div>

        {/* Hareketli Neon Işıklar */}
        <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-primary/10 rounded-full blur-[140px] animate-pulse"></div>
        <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-primary/5 rounded-full blur-[140px] animate-pulse" style={{ animationDelay: '2s' }}></div>

        {/* Dekoratif Çizgiler */}
        <div className="absolute top-0 left-1/4 w-[1px] h-full bg-gradient-to-b from-transparent via-primary/5 to-transparent"></div>
        <div className="absolute top-0 right-1/4 w-[1px] h-full bg-gradient-to-b from-transparent via-primary/5 to-transparent"></div>
      </div>

      <div className="w-full max-w-md relative animate-in fade-in zoom-in slide-in-from-bottom-8 duration-700">
        {/* Üst Logo ve Başlık Alanı */}
        <div className="flex flex-col items-center mb-8 relative">
          <div className="relative group">
            <div className="absolute inset-0 bg-primary/20 blur-2xl rounded-full scale-150 opacity-50 group-hover:opacity-80 transition-opacity"></div>
            <div className="h-24 w-24 rounded-[2rem] bg-surface-dark border border-primary/30 flex items-center justify-center relative z-10 shadow-2xl overflow-hidden">
               <div className="absolute inset-0 bg-gradient-to-br from-primary/10 to-transparent"></div>
               <span className="material-symbols-outlined text-primary text-6xl leading-none font-light">verified_user</span>
               {/* Köşe Detayları */}
               <div className="absolute top-2 left-2 w-2 h-2 border-t border-l border-primary/40"></div>
               <div className="absolute bottom-2 right-2 w-2 h-2 border-b border-r border-primary/40"></div>
            </div>
          </div>
          <div className="mt-6 text-center">
            <h1 className="text-4xl font-black text-white tracking-tighter flex items-center gap-2 justify-center">
              TOP<span className="text-primary">TECH</span>
            </h1>
            <div className="flex items-center gap-3 mt-2">
               <div className="h-[1px] w-8 bg-primary/20"></div>
               <p className="text-primary text-[9px] font-black uppercase tracking-[0.5em] opacity-80">SMART ECOSYSTEM</p>
               <div className="h-[1px] w-8 bg-primary/20"></div>
            </div>
          </div>
        </div>

        {/* Ana Form Kartı */}
        <div className="bg-surface-dark/40 backdrop-blur-3xl border border-white/5 rounded-[3rem] p-8 shadow-[0_20px_50px_rgba(0,0,0,0.5)] relative overflow-hidden group">
          {/* Tarayıcı Işık Efekti (Kenarda) */}
          <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-transparent via-primary/40 to-transparent"></div>

          {/* Segmented Switch */}
          <div className="bg-black/20 p-1.5 rounded-[1.5rem] flex mb-8 relative border border-white/5">
            <div 
              className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-primary rounded-[1.2rem] shadow-lg shadow-primary/20 transition-all duration-500 ease-out ${isLogin ? 'left-1.5' : 'left-[50%]'}`}
            ></div>
            <button 
              onClick={() => setIsLogin(true)}
              className={`relative z-10 flex-1 py-3 text-[10px] font-black tracking-widest transition-colors duration-300 ${isLogin ? 'text-background-dark' : 'text-slate-500'}`}
            >
              OTURUM AÇ
            </button>
            <button 
              onClick={() => setIsLogin(false)}
              className={`relative z-10 flex-1 py-3 text-[10px] font-black tracking-widest transition-colors duration-300 ${!isLogin ? 'text-background-dark' : 'text-slate-500'}`}
            >
              HESAP OLUŞTUR
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-2 group/input">
              <div className="flex justify-between items-center px-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] group-focus-within/input:text-primary transition-colors">Kullanıcı Kimliği</label>
                <span className="material-symbols-outlined text-[14px] text-slate-700 group-focus-within/input:text-primary">alternate_email</span>
              </div>
              <div className="relative">
                <input 
                  type="email" 
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="e-posta@toptech.com"
                  className="w-full bg-black/40 border border-white/5 rounded-2xl px-5 py-4 text-sm text-white focus:outline-none focus:border-primary/50 focus:ring-4 focus:ring-primary/5 transition-all placeholder:text-slate-800"
                />
              </div>
            </div>

            <div className="space-y-2 group/input">
              <div className="flex justify-between items-center px-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] group-focus-within/input:text-primary transition-colors">Erişim Anahtarı</label>
                <span className="material-symbols-outlined text-[14px] text-slate-700 group-focus-within/input:text-primary">lock_open</span>
              </div>
              <div className="relative">
                <input 
                  type="password" 
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="••••••••"
                  className="w-full bg-black/40 border border-white/5 rounded-2xl px-5 py-4 text-sm text-white focus:outline-none focus:border-primary/50 focus:ring-4 focus:ring-primary/5 transition-all placeholder:text-slate-800"
                />
              </div>
            </div>

            <button 
              type="submit"
              disabled={loading}
              className="w-full relative overflow-hidden group/btn active:scale-[0.98] transition-all"
            >
              <div className="absolute inset-0 bg-primary blur-xl opacity-20 group-hover/btn:opacity-40 transition-opacity"></div>
              <div className="relative bg-primary text-background-dark font-black text-sm h-16 rounded-2xl flex items-center justify-center gap-3 overflow-hidden">
                {loading ? (
                  <div className="flex items-center gap-3">
                     <span className="material-symbols-outlined animate-spin">data_usage</span>
                     <span className="tracking-widest text-[10px]">VERİ İŞLENİYOR...</span>
                  </div>
                ) : (
                  <>
                    <span className="tracking-[0.2em]">{isLogin ? 'SİSTEME GİRİŞ YAP' : 'ÜYELİĞİ TAMAMLA'}</span>
                    <span className="material-symbols-outlined font-bold">arrow_forward</span>
                  </>
                )}
                {/* Buton parlaması */}
                <div className="absolute top-0 -left-full w-full h-full bg-gradient-to-r from-transparent via-white/30 to-transparent group-hover/btn:left-full transition-all duration-1000"></div>
              </div>
            </button>
          </form>

          {/* Social Divider */}
          <div className="flex items-center gap-4 my-8">
            <div className="h-[1px] flex-1 bg-gradient-to-r from-transparent to-white/10"></div>
            <span className="text-[8px] font-black text-slate-600 uppercase tracking-[0.3em]">DIŞ BAĞLANTI</span>
            <div className="h-[1px] flex-1 bg-gradient-to-l from-transparent to-white/10"></div>
          </div>

          <button 
            onClick={handleGoogleLogin}
            disabled={loading}
            className="w-full bg-white/5 border border-white/10 text-white font-bold h-14 rounded-2xl flex items-center justify-center gap-3 hover:bg-white/10 active:scale-[0.98] transition-all relative group/google"
          >
            <div className="bg-white p-1 rounded-lg">
              <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" className="w-4 h-4" alt="Google" />
            </div>
            <span className="text-xs font-black tracking-wider uppercase opacity-80 group-hover/google:opacity-100">GOOGLE CLOUD AUTH</span>
          </button>

          {isLogin && (
            <button className="w-full text-center text-[9px] font-black text-slate-600 uppercase tracking-[0.2em] mt-8 hover:text-primary transition-colors">
              ERİŞİMİ Mİ KAYBETTİN?
            </button>
          )}
        </div>

        {/* Alt Bilgi */}
