             </div>
             <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1">Sulama Yapılmadı</h3>
             <p className="text-xs text-slate-500 dark:text-[#92c9a4] font-medium leading-relaxed">
               {selectedDay} {currentMonthName} tarihinde kayıtlı bir sulama oturumu bulunmuyor. Sistem otomatik modda hazır bekliyor.
             </p>
          </div>
        )}
      </div>

      {/* Session Details Modal */}
      <Modal 
        isOpen={isDetailModalOpen} 
        onClose={() => setIsDetailModalOpen(false)} 
