      >
        {selectedSession && (
          <div className="flex flex-col gap-6">
            <div className="flex items-center gap-5 p-5 bg-surface-dark/50 rounded-[2rem] border border-primary/20 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-2 opacity-5">
                <span className="material-symbols-outlined text-6xl">analytics</span>
              </div>
              <div className="h-16 w-16 rounded-2xl bg-primary text-background-dark flex items-center justify-center shadow-2xl relative z-10">
                <span className="material-symbols-outlined text-3xl font-bold">{selectedSession.icon}</span>
              </div>
              <div className="relative z-10">
                <h4 className="text-xl font-black text-white tracking-tight">{selectedSession.location}</h4>
                <p className="text-primary text-[10px] font-black uppercase tracking-[0.2em] mt-1">{selectedDay} {currentMonthName.toUpperCase()} {currentYear}</p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="bg-background-dark/50 p-5 rounded-[1.5rem] border border-border-dark/50 flex flex-col items-center justify-center">
                <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center mb-2">
                   <span className="material-symbols-outlined text-primary text-lg">play_arrow</span>
                </div>
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">BAŞLATILDI</p>
                <p className="text-xl font-black text-white tabular-nums">{selectedSession.startTime}</p>
              </div>
              <div className="bg-background-dark/50 p-5 rounded-[1.5rem] border border-border-dark/50 flex flex-col items-center justify-center">
                <div className="h-8 w-8 rounded-full bg-rose-500/10 flex items-center justify-center mb-2">
                   <span className="material-symbols-outlined text-rose-500 text-lg">stop</span>
                </div>
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">TAMAMLANDI</p>
