                {dayHasIrrigation && (
                  <div className={`absolute -bottom-1 w-1 h-1 rounded-full transition-all duration-500 ${isSelected ? 'bg-background-dark scale-150' : 'bg-primary'}`}></div>
                )}
              </div>
