      </div>

      {/* Simplified Status View */}
      <div className="flex flex-col gap-3 min-h-[160px]">
        {hasIrrigation ? (
          <div className="flex flex-col gap-4 p-6 rounded-[2rem] border border-primary/20 bg-white dark:bg-surface-dark shadow-xl animate-in fade-in slide-in-from-bottom-4 duration-500 overflow-hidden relative">
            <div className="absolute top-0 right-0 w-24 h-24 bg-primary/10 rounded-full blur-3xl -mr-12 -mt-12"></div>
            <div className="flex items-center gap-4">
              <div className="h-14 w-14 rounded-2xl bg-primary text-background-dark flex items-center justify-center shadow-lg">
                <span className="material-symbols-outlined text-3xl font-bold">water_drop</span>
              </div>
              <div>
                <h4 className="font-black text-slate-900 dark:text-white text-lg tracking-tight uppercase">{activeLandName}</h4>
                <div className="flex items-center gap-2 text-[10px] font-black text-primary uppercase tracking-widest mt-1">
                  <span className="h-2 w-2 rounded-full bg-primary"></span>
                  SULAMA BAŞARIYLA YAPILDI
                </div>
